n cavalrymen.","alternatives":[{"id":"01a218f9-36f2-70f5-b2a8-a2d91374d3ed","description":"Janissaries","correct_answer":true},{"id":"01a218f9-36f2-72ed-a26c-73f4891db797","description":"Samurai","correct_answer":false},{"id":"01a218f9-36f2-78dc-a7c8-dbcf60f782c0","description":"Ghazis","correct_answer":false},{"id":"01a218f9-36f2-7dca-a421-4b6cead4ae07","description":"Sipahis","correct_answer":false}]},{"id":"01a218f9-36f2-7b51-9848-cb408b7b06e0","locale":"en-US","category":"01a21312-b489-7ebc-94f2-41649ebfcaca","question":"On which continent was the historical country of Rhodesia?","difficulty":2,"explanation":"Rhodesia was in Africa, and its former territory is now largely Zimbabwe.","alternatives":[{"id":"01a218f9-36f2-7b0c-82e3-1660b37eff01","description":"Africa","correct_answer":true},{"id":"01a218f9-36f2-7435-b51e-3cdd0b120442","description":"Europe","correct_answer":false},{"id":"01a218f9-36f2-7d74-85b4-326694b0a074","description":"Asia","correct_answer":false},{"id":"01a218f9-36f2-71c8-88ac-5821d8b77a0d","description":"South America","correct_answer":false}]},{"id":"01a218f9-36f2-7344-bb89-2271f91825f9","locale":"en-US","category":"01a21312-b489-7ebc-94f2-41649ebfcaca","question":"In which year did the first human set foot on the moon?","difficulty":2,"explanation":"1969 was the year of the Apollo 11 landing. Neil Armstrong and Buzz Aldrin walked on the Moon while Michael Collins orbited above.","alternatives":[{"id":"01a218f9-36f2-7007-8957-05f660dccd61","description":"1969","correct_answer":true},{"id":"01a218f9-36f2-775a-95d9-10ed5a5910c2","description":"1948","correct_answer":false},{"id":"01a218f9-36f2-79ea-a9c0-abf03b689c3e","description":"1955","correct_answer":false},{"id":"01a218f9-36f2-7e45-b6ab-dbf492eb61ba","description":"1962","correct_answer":false}]},{"id":"01a218f9-36f2-7f85-8816-b22ce0b7feea","locale":"en-US","category":"01a21312-b489-7ebc-94f2-41649ebfcaca","question":"Introduced in 46 BC by Julius Caesar, how many months was the Julian calendar divided into?","difficulty":2,"explanation":"The Julian calendar had 12 months and used a leap day every fourth year to keep the calendar aligned with the seasons.","alternatives":[{"id":"01a218f9-36f2-7cc7-9ae5-3505dbfb3fcb","description":"12","correct_answer":true},{"id":"01a218f9-36f2-722c-8473-cc713a3731e8","description":"10","correct_answer":false},{"id":"01a218f9-36f2-7255-823b-d9326f067707","description":"13","correct_answer":false},{"id":"01a218f9-36f2-705a-9851-0194065a0bd7","description":"11","correct_answer":false}]},{"id":"01a218f9-36f2-78fe-bff1-66907d035eee","locale":"en-US","category":"01a21312-b489-7ebc-94f2-41649ebfcaca","question":"Which Russian revolutionary is most associated with the theory of \"permanent revolution\"?","difficulty":2,"explanation":"Leon Trotsky argued that Russia\u2019s revolution would have to continue beyond its initial democratic stage and spread internationally.","alternatives":[{"id":"01a218f9-36f2-7683-a6b2-dd9d616d3b01","description":"Leon Trotsky","correct_answer":true},{"id":"01a218f9-36f2-7d23-9fd4-6357d243c487","description":"Vladimir Lenin","correct_answer":false},{"id":"01a218f9-36f2-7e86-8e37-877f5c8b8dab","description":"Joseph Stalin","correct_answer":false},{"id":"01a218f9-36f2-793d-980a-03bd7c77c7b7","description":"Nikolai Bukharin","correct_answer":false}]},{"id":"01a218f9-36f2-7105-9c3d-c825822b7c86","locale":"en-US","category":"01a21312-b489-7ebc-94f2-41649ebfcaca","question":"With what country did the US almost start a war during the Cuban Missile Crisis?","difficulty":2,"explanation":"The Soviet Union placed nuclear missiles in Cuba, prompting a confrontation that ended after negotiations between Nikita Khrushchev and John F. Kennedy.","alternatives":[{"id":"01a218f9-36f2-7acd-8e71-906a204d95de","description":"Soviet Union","correct_answer":true},{"id":"01a218f9-36f2-7808-858f-3fef86600b24","description":"France","correct_answer":false},{"id":"01a218f9-36f2-7bd4-bede-00a4ebc8246d","description":"Mexico","correct_answer":false},{"id":"01a218f9-36f2-7742-8983-426d030c41af","description":"Brazil","correct_answer":false}]},{"id":"01a218f9-36f2-7988-a321-2f40d94e187c","locale":"en-US","category":"01a21312-b489-7ebc-94f2-41649ebfcaca","question":"Which ancient power defeated Vercingetorix\'s Gallic revolt in 52 BC?","difficulty":2,"explanation":"Rome crushed Vercingetorix\'s Gallic revolt at the siege of Alesia in 52 BC under Julius Caesar.","alternatives":[{"id":"01a218f9-36f2-79b3-a264-49ab2ebc47b7","description":"Rome","correct_answer":true},{"id":"01a218f9-36f2-75bc-addc-906c45024ddf","description":"Carthage","correct_answer":false},{"id":"01a218f9-36f2-7965-a680-f431a44b2018","description":"Macedon","correct_answer":false},{"id":"01a218f9-36f2-7c25-8fc9-789e30e25a08","description":"Persia","correct_answer":false}]},{"id":"01a218f9-36f2-7a01-851a-300c2756537b","locale":"en-US","category":"01a21312-b489-7ebc-94f2-41649ebfcaca","question":"Which of these people was a United States Army general during World War II?","difficulty":2,"explanation":"George S. Patton led the Third Army after the Normandy invasion, and his forces helped liberate much of France.","alternatives":[{"id":"01a218f9-36f2-7d78-88e8-b5ca9e4c532b","description":"George S. Patton","correct_answer":true},{"id":"01a218f9-36f2-7968-8a53-0a0168825775","description":"David Dixon Porter","correct_answer":false},{"id":"01a218f9-36f2-779e-addd-9c5deffb7a99","description":"George Elliot","correct_answer":false},{"id":"01a218f9-36f2-7f7e-970f-109f060557dc","description":"Philip Sheridan","correct_answer":false}]},{"id":"01a218f9-36f2-72cf-bde3-f90ca1cd4fcc","locale":"en-US","category":"01a21312-b489-7ebc-94f2-41649ebfcaca","question":"In which year did the American Civil War end?","difficulty":2,"explanation":"The Civil War ended in 1865; Lee\'s surrender at Appomattox Court House in April marked a decisive turning point, though fighting continued briefly elsewhere.","alternatives":[{"id":"01a218f9-36f2-78